import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.CLq81i8L.js";const g=JSON.parse('{"title":"AI Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"en/ai/architecture.md","filePath":"en/ai/architecture.md","lastUpdated":1785296213000}'),r={name:"en/ai/architecture.md"};function n(s,t,i,c,l,p){return a(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="ai-architecture" tabindex="-1">AI Architecture <a class="header-anchor" href="#ai-architecture" aria-label="Permalink to &quot;AI Architecture&quot;">​</a></h1><blockquote><p>Overall architecture of the <code>ai/</code> project: Chat LangGraph and Agent Workflow dual engines. For the <strong>three-capability relationship, JWT, credentials, open-source small-platform positioning</strong> see <a href="./platform.html">platform.md</a>.</p></blockquote><p><strong>Doc version</strong>: v7 (2026-07-13) - removed legacy architecture references, aligned with current implementation</p><hr><h2 id="_1-project-structure" tabindex="-1">1. Project Structure <a class="header-anchor" href="#_1-project-structure" aria-label="Permalink to &quot;1. Project Structure&quot;">​</a></h2><p><code>ai/</code> is a multi-package parallel repo (not a monorepo workspace); each sub-package has its own <code>package.json</code> and independent build/deploy.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ai/</span></span>
<span class="line"><span>├── app/              @ai-app                         Vue 3 micro-frontend: Chat, RAG, monitoring, workflow designer, plugin center</span></span>
<span class="line"><span>├── shared/           @schema-platform/ai-shared       cross-end types, events, prompt, workflow domain models</span></span>
<span class="line"><span>└── docs/             this docs directory</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Package</th><th>Consumers</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>@ai-app</code></td><td>shell (qiankun)</td><td>Frontend UI: Chat, workflow designer, execution monitoring, RAG, plugin center <code>/plugins</code></td></tr><tr><td><code>@schema-platform/platform-shared/ai</code></td><td>app, server</td><td>Event protocol, tool names, prompt, workflow types</td></tr></tbody></table><p><strong>Dependency direction</strong>: <code>app -&gt; ai-shared + platform-shared</code>; <code>server -&gt; ai-shared</code>.</p><p><strong>Plugin center</strong>: Expert / Skill / Tool / MCP are configured per directory in <code>server/config/plugins/</code> (see <a href="./plugin.html">plugin.md</a>); supports <code>plugin:pack</code> / <code>plugin:install</code> and SIGHUP hot-reload.</p><p><strong>In-repo dev</strong>: <code>app/package.json</code> references ai-shared via <code>file:../shared</code>; Vite alias can connect directly to shared source, so dev/build picks up shared changes automatically.</p><hr><h2 id="_2-dual-agent-system" tabindex="-1">2. Dual Agent System <a class="header-anchor" href="#_2-dual-agent-system" aria-label="Permalink to &quot;2. Dual Agent System&quot;">​</a></h2><p>The platform runs two parallel agent engines, sharing the MCP tool registry and <code>@schema-platform/platform-shared/ai</code>, but with different execution models:</p><table tabindex="0"><thead><tr><th>Dimension</th><th>Chat LangGraph</th><th>Agent Workflow DAG</th></tr></thead><tbody><tr><td>Entry</td><td>AiChatView, editor/flow embed</td><td>Designer, REST API, Webhook, Chat workflow pick</td></tr><tr><td>Engine</td><td><code>server/src/ai/graph/graph.ts</code></td><td><code>server/src/ai/services/agentWorkflowExecutor.ts</code></td></tr><tr><td>Orchestration model</td><td>LangGraph StateGraph + Checkpoint</td><td>n8n-style sequential DAG traversal</td></tr><tr><td>State persistence</td><td>LangGraph checkpointer</td><td>MongoDB <code>AgentWorkflowExecution</code></td></tr><tr><td>HITL</td><td>LangGraph <code>interrupt</code> / <code>chat:resume</code></td><td><code>hitl</code> node + <code>POST .../resume</code></td></tr><tr><td>Tools</td><td>MCP Bridge + LangGraph-specific tools</td><td>same + built-in <code>http_request</code></td></tr><tr><td>Docs</td><td><a href="./agent.html">agent.md</a></td><td><a href="./agent-workflow.html">agent-workflow.md</a></td></tr></tbody></table><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ┌─────────────────────────────────────┐</span></span>
<span class="line"><span>                    │     @schema-platform/ai-shared      │</span></span>
<span class="line"><span>                    │  events · toolNames · promptBuilder │</span></span>
<span class="line"><span>                    │  agentWorkflow · document           │</span></span>
<span class="line"><span>                    └─────────────────────────────────────┘</span></span>
<span class="line"><span>                           ▲                    ▲</span></span>
<span class="line"><span>                           │                    │</span></span>
<span class="line"><span>              ┌────────────┴──────┐   ┌────────┴────────────┐</span></span>
<span class="line"><span>              │  Chat LangGraph   │   │  Agent Workflow     │</span></span>
<span class="line"><span>              │  (conversational) │   │  (visual orchestration)│</span></span>
<span class="line"><span>              └────────────┬──────┘   └────────┬────────────┘</span></span>
<span class="line"><span>                           │                    │</span></span>
<span class="line"><span>                           └────────┬───────────┘</span></span>
<span class="line"><span>                                    ▼</span></span>
<span class="line"><span>                         ┌─────────────────────┐</span></span>
<span class="line"><span>                         │  tools/registry.ts  │</span></span>
<span class="line"><span>                         │  MCP Bridge (5 svcs)│</span></span>
<span class="line"><span>                         └─────────────────────┘</span></span></code></pre></div><hr><h2 id="_3-chat-langgraph-architecture" tabindex="-1">3. Chat LangGraph Architecture <a class="header-anchor" href="#_3-chat-langgraph-architecture" aria-label="Permalink to &quot;3. Chat LangGraph Architecture&quot;">​</a></h2><h3 id="_3-1-compiled-graph-nodes-current-code" tabindex="-1">3.1 Compiled Graph Nodes (current code) <a class="header-anchor" href="#_3-1-compiled-graph-nodes-current-code" aria-label="Permalink to &quot;3.1 Compiled Graph Nodes (current code)&quot;">​</a></h3><p>Nodes registered in <code>server/src/ai/graph/graph.ts</code>:</p><table tabindex="0"><thead><tr><th>Node</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>router</code></td><td>Explicit mode routing, keyword multi-intent detection, task chain pre-build</td></tr><tr><td><code>requirementAnalyzer</code></td><td>v2: deep requirement analysis (on by default)</td></tr><tr><td><code>requirementConfirm</code></td><td>v2: requirement confirmation card (HITL)</td></tr><tr><td><code>taskPlanner</code></td><td>v2: task planning, generates task chain</td></tr><tr><td><code>taskChain</code></td><td>Task chain advancement, agent collaboration insertion; writes <code>session.currentExpertId</code></td></tr><tr><td><strong><code>pluginExpert</code></strong></td><td><strong>The only expert execution node</strong> (Registry prompt/tools + domain context)</td></tr><tr><td><code>allTools</code></td><td>ToolNode execution (with error fallback)</td></tr><tr><td><code>afterTools</code></td><td>Post-tool processing, collaboration request extraction, context passing</td></tr><tr><td><code>summarizer</code></td><td>Multi-step task result summary</td></tr></tbody></table><p>Expert resolution &amp; session sync: <code>graph/resolveGraphExpert.ts</code>. Domain user context (Schema/Flow/collaboration): <code>graph/expertUserContext.ts</code>.</p><blockquote><p><strong>Baseline 1.0</strong>: removed the <code>editor</code> / <code>flow</code> / <code>page</code> / <code>general</code> graph nodes and <code>*Agent.ts</code>; both built-in and third-party experts go through <code>pluginExpert</code>.</p></blockquote><blockquote><p><strong>Note</strong>: <code>thinker</code> and <code>qualityCheck</code> are only defined in <code>events.ts</code> types, <strong>not registered as graph nodes</strong>; the server does not emit the corresponding events.</p></blockquote><h3 id="_3-2-v2-default-flow" tabindex="-1">3.2 v2 Default Flow <a class="header-anchor" href="#_3-2-v2-default-flow" aria-label="Permalink to &quot;3.2 v2 Default Flow&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>START</span></span>
<span class="line"><span>  -&gt; router</span></span>
<span class="line"><span>  -&gt; requirementAnalyzer</span></span>
<span class="line"><span>      ├─ (needs confirm) -&gt; requirementConfirm -&gt; taskPlanner</span></span>
<span class="line"><span>      └─ (skip confirm) ─────────────────────-&gt; taskPlanner</span></span>
<span class="line"><span>  -&gt; taskPlanner -&gt; taskChain</span></span>
<span class="line"><span>  -&gt; taskChain -&gt; pluginExpert | summarizer</span></span>
<span class="line"><span>  -&gt; pluginExpert</span></span>
<span class="line"><span>      ├─ (has tool_calls) -&gt; allTools -&gt; afterTools -&gt; taskChain | pluginExpert | summarizer</span></span>
<span class="line"><span>      └─ (no tool_calls) -&gt; END or summarizer / taskChain</span></span>
<span class="line"><span>  -&gt; summarizer -&gt; END</span></span></code></pre></div><p><strong>Environment variables</strong>:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>AI_ENABLE_TASK_PLANNER</code></td><td><code>true</code></td><td>Enable the task planning node</td></tr></tbody></table><h3 id="_3-3-experts-plugin-center" tabindex="-1">3.3 Experts &amp; Plugin Center <a class="header-anchor" href="#_3-3-experts-plugin-center" aria-label="Permalink to &quot;3.3 Experts &amp; Plugin Center&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Concept</th><th>Description</th></tr></thead><tbody><tr><td><strong>Registry expert</strong></td><td><code>server/config/plugins/experts/*.json</code>, e.g. <code>platform.editor</code></td></tr><tr><td><strong><code>legacyAgentKey</code></strong></td><td>Scheduling key for the four built-in experts (<code>editor</code>/<code>flow</code>/<code>page</code>/<code>general</code>), used for task chain, collaboration, explicit <code>context.source</code>; <strong>no longer</strong> corresponds to independent graph nodes</td></tr><tr><td><strong><code>session.currentExpertId</code></strong></td><td>Runtime authoritative expert id; <code>pluginExpert</code> executes by it</td></tr><tr><td><strong>System Prompt</strong></td><td><code>buildExpertSystemPrompt</code> (plugin <code>systemPrompt</code> + Skill); <code>dynamicPrompt</code> goes through ai-shared <code>promptBuilder</code></td></tr><tr><td><strong>Third-party expert</strong></td><td>Just add plugin JSON + pack; no new <code>graph/*Agent.ts</code> needed</td></tr></tbody></table><h3 id="_3-4-key-behaviors" tabindex="-1">3.4 Key Behaviors <a class="header-anchor" href="#_3-4-key-behaviors" aria-label="Permalink to &quot;3.4 Key Behaviors&quot;">​</a></h3><ul><li><strong>Explicit mode</strong>: when <code>context.source === editor|flow|page</code>, skip keyword guessing and enter the corresponding expert directly</li><li><strong>Multi-intent</strong>: router detects &quot;page + form/flow&quot; combos and pre-builds a task chain</li><li><strong>Tool loop</strong>: at most 3 tool iterations per agent round; global <code>session.maxNodeExecutions</code> prevents infinite loops</li><li><strong>Collaboration</strong>: <code>request_collaboration</code> tool -&gt; <code>afterTools</code> extracts -&gt; <code>taskChain</code> inserts a collaboration step</li><li><strong>Streaming</strong>: WebSocket / Socket.IO; event types in <a href="./events.html">events.md</a></li></ul><hr><h2 id="_4-agent-workflow-architecture-summary" tabindex="-1">4. Agent Workflow Architecture (summary) <a class="header-anchor" href="#_4-agent-workflow-architecture-summary" aria-label="Permalink to &quot;4. Agent Workflow Architecture (summary)&quot;">​</a></h2><p>Visual DAG orchestration system; see <a href="./agent-workflow.html">agent-workflow.md</a> for details.</p><h3 id="_4-1-lifecycle" tabindex="-1">4.1 Lifecycle <a class="header-anchor" href="#_4-1-lifecycle" aria-label="Permalink to &quot;4.1 Lifecycle&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Design (draftGraph) -&gt; Save (version snapshot) -&gt; Publish (publishedGraph + publishId) -&gt; Execute -&gt; Monitor</span></span></code></pre></div><h3 id="_4-2-node-categories-baseline-1-0" tabindex="-1">4.2 Node Categories (baseline 1.0) <a class="header-anchor" href="#_4-2-node-categories-baseline-1-0" aria-label="Permalink to &quot;4.2 Node Categories (baseline 1.0)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Category</th><th>Node types</th></tr></thead><tbody><tr><td>Trigger</td><td><code>manual-trigger</code>, <code>webhook-trigger</code></td></tr><tr><td>AI</td><td><code>llm</code>, <code>document-parse</code>, <code>vision-analyze</code>, <code>conversation-memory</code>, <code>image-generate</code>, <code>ppt-generate</code></td></tr><tr><td>Conversational intelligence</td><td><code>intent-router</code>, <code>requirement-analyzer</code>, <code>task-planner</code>, <code>task-chain</code>, <code>collaboration-router</code>, <code>summarizer</code></td></tr><tr><td>Expert</td><td><code>agent-intent</code> (auto-routing), <code>expert</code> (<code>expertId</code> -&gt; plugin center)</td></tr><tr><td>Tool</td><td><code>tool</code> (<code>toolName</code> -&gt; Registry / MCP)</td></tr><tr><td>Logic</td><td><code>if</code>, <code>hitl</code>, <code>end</code></td></tr></tbody></table><p>Palette expert and tool entries come from the plugin registry (<code>usePluginRegistry</code>), not hardcoded <code>agent-editor</code> / <code>tool-mcp-*</code>.</p><h3 id="_4-3-built-in-templates-16" tabindex="-1">4.3 Built-in Templates (16) <a class="header-anchor" href="#_4-3-built-in-templates-16" aria-label="Permalink to &quot;4.3 Built-in Templates (16)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Name</th><th>Trigger</th></tr></thead><tbody><tr><td><code>blank</code></td><td>Blank workflow</td><td>Manual</td></tr><tr><td><code>document-summary</code></td><td>Document summary</td><td>Webhook</td></tr><tr><td><code>doc-image-recognition</code></td><td>Document/image recognition</td><td>Manual</td></tr><tr><td><code>intelligent-assistant</code></td><td>Smart assistant Q&amp;A</td><td>Manual</td></tr><tr><td><code>contract-extract</code></td><td>Contract clause extraction</td><td>Webhook</td></tr><tr><td><code>kb-faq</code></td><td>Knowledge base FAQ generation</td><td>Webhook</td></tr><tr><td><code>http-notify</code></td><td>HTTP callback notification</td><td>Webhook</td></tr><tr><td><code>rag-ingest-qa</code></td><td>RAG ingest QA</td><td>Webhook</td></tr><tr><td><code>multi-doc-batch</code></td><td>Multi-doc batch processing</td><td>Webhook</td></tr><tr><td><code>smart-suggestions</code></td><td>Smart suggestions</td><td>Manual</td></tr><tr><td><code>smart-action-proposals</code></td><td>Smart action proposals</td><td>Webhook</td></tr><tr><td><code>image-text-generation</code></td><td>Image-text generation</td><td>Manual</td></tr><tr><td><code>ppt-generation</code></td><td>PPT generation</td><td>Manual</td></tr><tr><td><code>image-analysis</code></td><td>Image smart analysis</td><td>Manual</td></tr><tr><td><code>chat-parity-assistant</code></td><td>Smart assistant v2</td><td>Manual</td></tr><tr><td><code>requirement-gated-build</code></td><td>Requirement-gated build</td><td>Manual</td></tr></tbody></table><p>Full template flow diagrams in <a href="./agent-workflow.html">agent-workflow.md</a>. Definitions and factory functions in <code>shared/platform-shared/ai/agentWorkflow.ts</code>.</p><h3 id="_4-4-frontend-routes" tabindex="-1">4.4 Frontend Routes <a class="header-anchor" href="#_4-4-frontend-routes" aria-label="Permalink to &quot;4.4 Frontend Routes&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Route</th><th>View</th></tr></thead><tbody><tr><td><code>/workflows</code></td><td>Workflow list</td></tr><tr><td><code>/workflows/:id</code></td><td>Designer</td></tr><tr><td><code>/workflows/:id/executions</code></td><td>Execution history</td></tr><tr><td><code>/executions/:id</code></td><td>Execution detail (node-level monitoring)</td></tr></tbody></table><p>Chat can select a published workflow as the chat backend via <code>AgentWorkflowPicker</code>.</p><hr><h2 id="_5-tool-layer" tabindex="-1">5. Tool Layer <a class="header-anchor" href="#_5-tool-layer" aria-label="Permalink to &quot;5. Tool Layer&quot;">​</a></h2><h3 id="_5-1-three-layer-tools" tabindex="-1">5.1 Three-layer Tools <a class="header-anchor" href="#_5-1-three-layer-tools" aria-label="Permalink to &quot;5.1 Three-layer Tools&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>LangGraph Chat / Workflow Executor</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>         ▼</span></span>
<span class="line"><span>   tools/registry.ts</span></span>
<span class="line"><span>         │</span></span>
<span class="line"><span>    ┌────┴────────────────┐</span></span>
<span class="line"><span>    ▼                     ▼</span></span>
<span class="line"><span> MCP Bridge            LangGraph-specific</span></span>
<span class="line"><span> (5 MCP servers)       (no prefix naming)</span></span></code></pre></div><p><strong>MCP naming</strong>: <code>{domain}__{action}</code> (e.g. <code>schema__search</code>)</p><p><strong>LangGraph-specific</strong> (no <code>__</code> prefix): <code>update_schema</code>, <code>generate_schema</code>, <code>update_flow</code>, <code>save_and_bind_schema</code>, <code>bind_schema_to_flow_node</code>, <code>request_collaboration</code>, <code>rag_index</code></p><p><strong>Workflow-specific</strong>: <code>http_request</code> (built into the executor, not in the MCP registry)</p><p>Authoritative definition: <code>shared/platform-shared/ai/toolNames.ts</code> (MCP spec name <code>{domain}__{action}</code>, no legacy alias table).</p><p>See <a href="./tool.html">tool.md</a>, <a href="./mcp.html">mcp.md</a>.</p><h3 id="_5-2-mcp-servers-5" tabindex="-1">5.2 MCP Servers (5) <a class="header-anchor" href="#_5-2-mcp-servers-5" aria-label="Permalink to &quot;5.2 MCP Servers (5)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Server</th><th>Domain prefix</th><th>Responsibility</th></tr></thead><tbody><tr><td>schemaServer</td><td><code>schema__</code></td><td>Schema search, detail, validation</td></tr><tr><td>flowServer</td><td><code>flow__</code></td><td>Flow search, detail, validation, user</td></tr><tr><td>widgetServer</td><td><code>widget__</code></td><td>Widget catalog query and validation</td></tr><tr><td>ragServer</td><td><code>rag__</code></td><td>Knowledge base retrieval</td></tr><tr><td>industryServer</td><td><code>industry__</code></td><td>Industry template search and validation</td></tr></tbody></table><p>Bridge implementation: <code>server/src/ai/mcp/bridge.ts</code> (InMemoryTransport -&gt; LangGraph StructuredTool).</p><hr><h2 id="_6-event-protocol" tabindex="-1">6. Event Protocol <a class="header-anchor" href="#_6-event-protocol" aria-label="Permalink to &quot;6. Event Protocol&quot;">​</a></h2><p>Unified event types are defined in <code>shared/platform-shared/ai/events.ts</code> and pushed to the frontend via WebSocket <code>chat:event</code>.</p><ul><li><strong>v1</strong>: text stream, schema/flow generation, tool calls, task chain, HITL, done/error</li><li><strong>v2</strong>: requirement analysis, task planning (implemented and emitted)</li><li><strong>v2 reserved</strong>: <code>thinker_*</code>, <code>quality_check_*</code> (types defined, graph nodes not implemented)</li></ul><p>Full list in <a href="./events.html">events.md</a>.</p><hr><h2 id="_7-server-api-overview" tabindex="-1">7. Server API Overview <a class="header-anchor" href="#_7-server-api-overview" aria-label="Permalink to &quot;7. Server API Overview&quot;">​</a></h2><p>Chat and Workflow REST / WebSocket endpoints are provided by <code>server/src/ai/</code> (the frontend adapts to existing APIs; server code is not modified).</p><h3 id="chat-websocket" tabindex="-1">Chat (WebSocket) <a class="header-anchor" href="#chat-websocket" aria-label="Permalink to &quot;Chat (WebSocket)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>Direction</th><th>Description</th></tr></thead><tbody><tr><td><code>chat:send</code></td><td>Client -&gt; Server</td><td>Send message</td></tr><tr><td><code>chat:event</code></td><td>Server -&gt; Client</td><td>Stream events</td></tr><tr><td><code>chat:resume</code></td><td>Client -&gt; Server</td><td>HITL resume</td></tr><tr><td><code>chat:cancel</code></td><td>Client -&gt; Server</td><td>Cancel generation</td></tr></tbody></table><h3 id="workflow-rest-api-ai" tabindex="-1">Workflow (REST, <code>/api/ai</code>) <a class="header-anchor" href="#workflow-rest-api-ai" aria-label="Permalink to &quot;Workflow (REST, \`/api/ai\`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Description</th></tr></thead><tbody><tr><td>GET/POST</td><td><code>/workflows</code></td><td>List / create</td></tr><tr><td>GET/PUT/DELETE</td><td><code>/workflows/:id</code></td><td>Detail / update / delete</td></tr><tr><td>POST</td><td><code>/workflows/:id/publish</code></td><td>Publish</td></tr><tr><td>GET</td><td><code>/workflows/:id/versions</code></td><td>Version list</td></tr><tr><td>POST</td><td><code>/workflows/:id/execute</code></td><td>Manual execute (JWT)</td></tr><tr><td>POST</td><td><code>/workflows/invoke/:slugOrId</code></td><td>External integration execute (<code>X-API-Key</code> / <code>X-Workflow-Key</code>)</td></tr><tr><td>GET</td><td><code>/workflows/invoke/executions/:id</code></td><td>Invoke execution query</td></tr><tr><td>GET</td><td><code>/workflow-executions</code></td><td>Execution list</td></tr><tr><td>GET</td><td><code>/workflow-executions/:id</code></td><td>Execution detail</td></tr><tr><td>POST</td><td><code>/workflow-executions/:id/resume</code></td><td>HITL resume</td></tr><tr><td>POST</td><td><code>/workflow-executions/:id/continue</code></td><td>Multi-turn continue</td></tr><tr><td>*</td><td><code>/webhooks/*path</code></td><td>Webhook trigger</td></tr></tbody></table><hr><h2 id="_8-related-docs" tabindex="-1">8. Related Docs <a class="header-anchor" href="#_8-related-docs" aria-label="Permalink to &quot;8. Related Docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Content</th></tr></thead><tbody><tr><td><a href="./agent.html">agent.md</a></td><td>Chat expert agent details</td></tr><tr><td><a href="./agent-workflow.html">agent-workflow.md</a></td><td>Full workflow orchestration guide</td></tr><tr><td><a href="./ai-shared.html">ai-shared.md</a></td><td>Shared package API and types</td></tr><tr><td><a href="./tool.html">tool.md</a></td><td>Tool registration and extension</td></tr><tr><td><a href="./mcp.html">mcp.md</a></td><td>MCP protocol and servers</td></tr><tr><td><a href="./events.html">events.md</a></td><td>Full event protocol list</td></tr><tr><td><a href="./design/README.html">design/</a></td><td>Product design: wireframes, interaction flows, runtime graphs</td></tr><tr><td><a href="./README.html">README.md</a></td><td>Quick start and doc index</td></tr></tbody></table>`,73)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
